import React, { useEffect, useState } from "react";
import Card from "./Card"; // Custom Card component for metrics

const MonitoringWidget = () => {
  const [metrics, setMetrics] = useState([]);

  useEffect(() => {
    // Fetch the metrics here
    setMetrics([
      { title: "CPU Usage", value: "35%" },
      { title: "Memory Usage", value: "60%" },
      { title: "Disk Space", value: "80%" },
      { title: "Network", value: "Good" },
    ]);
  }, []);

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-6">
      {metrics.map((metric, index) => (
        <Card key={index} title={metric.title} value={metric.value} />
      ))}
    </div>
  );
};

export default MonitoringWidget;
